// ============================================================
// ERROR CLASSIFIER & SOLUTION ENGINE
// ============================================================
// Classifies errors into categories and suggests solutions.
// Also determines if the error is auto-retryable.
// ============================================================

const errorData = $input.first().json;

// Extract error details from the Error Trigger payload
const execution = errorData.execution || {};
const workflow = errorData.workflow || {};
const errorMessage = execution.error?.message || execution.lastNodeExecuted?.error?.message || 'Unknown error';
const errorStack = execution.error?.stack || '';
const failedNodeName = execution.lastNodeExecuted || 'Unknown';
const workflowName = workflow.name || 'Unknown Workflow';
const workflowId = workflow.id || '';
const executionId = execution.id || '';
const executionMode = execution.mode || 'unknown';
const timestamp = new Date().toISOString();

// ---- ERROR CLASSIFICATION ENGINE ----
const msg = errorMessage.toLowerCase();
const stack = errorStack.toLowerCase();

let errorCategory = 'Unknown';
let severity = 'Medium';
let suggestedSolution = '';
let autoRetryable = false;
let autoFixAction = 'none';

// --- Authentication / Credential Errors ---
if (msg.includes('401') || msg.includes('unauthorized') || msg.includes('authentication') || msg.includes('invalid api key') || msg.includes('credential') || msg.includes('forbidden') || msg.includes('403')) {
  errorCategory = 'Authentication Error';
  severity = 'Critical';
  suggestedSolution = '1. Go to n8n Credentials page\n2. Find the credential used by node: ' + failedNodeName + '\n3. Re-enter/refresh the API key or token\n4. Test the credential\n5. Re-execute the workflow';
  autoRetryable = false;
}
// --- Rate Limiting ---
else if (msg.includes('429') || msg.includes('rate limit') || msg.includes('too many requests') || msg.includes('throttl')) {
  errorCategory = 'Rate Limit Error';
  severity = 'Medium';
  suggestedSolution = '1. Wait 5-10 minutes and retry\n2. Reduce workflow execution frequency\n3. Add a Wait node before API calls\n4. Enable batching in workflow settings';
  autoRetryable = true;
  autoFixAction = 'retry_with_delay';
}
// --- Network / Timeout Errors ---
else if (msg.includes('timeout') || msg.includes('econnrefused') || msg.includes('enotfound') || msg.includes('network') || msg.includes('socket') || msg.includes('econnreset') || msg.includes('etimedout') || msg.includes('502') || msg.includes('503') || msg.includes('504')) {
  errorCategory = 'Network / Timeout Error';
  severity = 'Medium';
  suggestedSolution = '1. Check if the external service is operational\n2. Verify the URL/hostname is correct\n3. Auto-retry is enabled for this error type\n4. If persistent, check n8n server DNS and firewall settings';
  autoRetryable = true;
  autoFixAction = 'retry_immediate';
}
// --- Data / Validation Errors ---
else if (msg.includes('validation') || msg.includes('required field') || msg.includes('missing') || msg.includes('undefined') || msg.includes('null') || msg.includes('cannot read prop') || msg.includes('is not defined') || msg.includes('invalid') || msg.includes('parse error') || msg.includes('json')) {
  errorCategory = 'Data Validation Error';
  severity = 'High';
  suggestedSolution = '1. Check input data format in the failed node: ' + failedNodeName + '\n2. Verify all required fields are populated\n3. Add a Set/Code node before to sanitize data\n4. Check expressions for typos or incorrect references\n5. Test with sample data in the node editor';
  autoRetryable = false;
}
// --- Resource Not Found ---
else if (msg.includes('404') || msg.includes('not found') || msg.includes('does not exist') || msg.includes('no such')) {
  errorCategory = 'Resource Not Found';
  severity = 'High';
  suggestedSolution = '1. Verify the resource ID/name in node: ' + failedNodeName + '\n2. Check if the Airtable base/table still exists\n3. Verify the API endpoint URL is correct\n4. The referenced record may have been deleted';
  autoRetryable = false;
}
// --- Quota / Billing Errors ---
else if (msg.includes('quota') || msg.includes('limit exceeded') || msg.includes('billing') || msg.includes('payment') || msg.includes('subscription')) {
  errorCategory = 'Quota / Billing Error';
  severity = 'Critical';
  suggestedSolution = '1. Check your API plan usage/limits\n2. Upgrade plan if limits are consistently hit\n3. Reduce data volume per execution\n4. Check billing dashboard for the service';
  autoRetryable = false;
}
// --- Code Execution Errors ---
else if (msg.includes('syntax') || msg.includes('referenceerror') || msg.includes('typeerror') || msg.includes('rangeerror') || stack.includes('code node')) {
  errorCategory = 'Code Node Error';
  severity = 'High';
  suggestedSolution = '1. Open the Code node: ' + failedNodeName + '\n2. Check for JavaScript syntax errors\n3. Verify variable names and data references\n4. Test with console.log() to debug data shape\n5. Check $input.all() returns expected data';
  autoRetryable = false;
}
// --- Permission Errors ---
else if (msg.includes('permission') || msg.includes('access denied') || msg.includes('scope') || msg.includes('insufficient')) {
  errorCategory = 'Permission Error';
  severity = 'Critical';
  suggestedSolution = '1. Check API key/token permissions/scopes\n2. For Slack: ensure bot has chat:write scope\n3. For Google Sheets: share the sheet with the service account\n4. For Airtable: verify token has read/write access to the base';
  autoRetryable = false;
}
// --- Server / Internal Errors ---
else if (msg.includes('500') || msg.includes('internal server') || msg.includes('unexpected error')) {
  errorCategory = 'External Service Error (5xx)';
  severity = 'Medium';
  suggestedSolution = '1. The external service had an internal error\n2. Auto-retry is enabled for this error type\n3. If persistent, check the service status page\n4. Contact the service provider if it continues';
  autoRetryable = true;
  autoFixAction = 'retry_with_delay';
}
// --- Fallback ---
else {
  errorCategory = 'Unclassified Error';
  severity = 'Medium';
  suggestedSolution = '1. Review the full error message below\n2. Check the failed node: ' + failedNodeName + '\n3. Look at the execution log in n8n\n4. Check n8n community forum for similar errors\n5. Full error: ' + errorMessage;
  autoRetryable = false;
}

// ---- BUILD OUTPUT ----
return [{
  json: {
    // For Google Sheets logging
    timestamp: timestamp,
    workflow_name: workflowName,
    workflow_id: workflowId,
    execution_id: executionId,
    execution_mode: executionMode,
    failed_node: failedNodeName,
    error_category: errorCategory,
    severity: severity,
    error_message: errorMessage.substring(0, 500),
    suggested_solution: suggestedSolution,
    auto_retryable: autoRetryable ? 'Yes' : 'No',
    auto_fix_action: autoFixAction,
    resolution_status: autoRetryable ? 'Pending Auto-Retry' : 'Requires Manual Fix',
    resolved_at: '',
    // For Slack notification
    _slack_message: buildSlackMessage({
      workflowName, workflowId, executionId, failedNodeName,
      errorCategory, severity, errorMessage, suggestedSolution, autoRetryable
    })
  }
}];

function buildSlackMessage(d) {
  const severityEmoji = d.severity === 'Critical' ? ':red_circle:' : d.severity === 'High' ? ':large_orange_circle:' : ':large_yellow_circle:';
  const retryStatus = d.autoRetryable ? ':arrows_counterclockwise: Auto-retry scheduled' : ':wrench: Manual fix required';

  let lines = [];
  lines.push(severityEmoji + ' *n8n Workflow Error Alert*');
  lines.push('');
  lines.push('*Workflow:* ' + d.workflowName);
  lines.push('*Failed Node:* `' + d.failedNodeName + '`');
  lines.push('*Error Type:* ' + d.errorCategory + ' (' + d.severity + ')');
  lines.push('*Status:* ' + retryStatus);
  lines.push('');
  lines.push('*Error Message:*');
  lines.push('```' + d.errorMessage.substring(0, 300) + '```');
  lines.push('');
  lines.push('*Suggested Solution:*');
  lines.push(d.suggestedSolution.replace(/\n/g, '\n'));
  lines.push('');
  lines.push('*Links:*');
  lines.push('- <https://n8n.aimanagingservices.com/workflow/' + d.workflowId + '|Open Workflow>');
  lines.push('- <https://n8n.aimanagingservices.com/executions/' + d.executionId + '|View Execution>');
  lines.push('');
  lines.push('_' + new Date().toLocaleString('en-US', {timeZone: 'America/New_York'}) + ' ET_');

  return lines.join('\n');
}
